output_text:
[
  {
    "id": "must_take_cart_at_bay",
    "text": "On entering the store, the customer is obliged to take the available cart from the cart bay before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_cart_bay": "at(1,5)",
        "cart_waiting_at_bay": "cartAt(1,5)"
      },
      "events": {
        "take_cart_from_bay": {
          "pre": {
            "and": [
              "at_cart_bay",
              "cart_waiting_at_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart_from_bay"
    }
  },
  {
    "id": "no_bypass_cart_bay",
    "text": "A customer must not walk past the occupied cart bay to the east without first taking the cart.",
    "abstraction": {
      "state_properties": {
        "at_cart_bay": "at(1,5)",
        "cart_waiting_at_bay": "cartAt(1,5)",
        "not_holding_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "bypass_cart_bay": {
          "pre": {
            "and": [
              "at_cart_bay",
              "cart_waiting_at_bay",
              "not_holding_cart",
              "E"
            ]
          },
          "post": "at(2,5)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "bypass_cart_bay"
    }
  },
  {
    "id": "cart_required_for_items",
    "text": "Items may only be picked up from shelves while the customer has a shopping cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        },
        "pickup_item_with_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers are forbidden from carrying merchandise by hand rather than keeping it in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_to_counter",
    "text": "After taking a cart, the customer is obliged to return or park it at the service counter before leaving the store.",
    "abstraction": {
      "state_properties": {
        "at_cart_bay": "at(1,5)",
        "at_service_counter": "at(0,1)",
        "cart_parked_at_counter": "cartAt(0,1)"
      },
      "events": {
        "take_cart_from_bay": {
          "pre": {
            "and": [
              "at_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "park_cart_at_counter": {
          "pre": {
            "and": [
              "at_service_counter",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_counter"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart_from_bay",
      "discharge": "park_cart_at_counter"
    }
  },
  {
    "id": "only_drop_cart_at_counter",
    "text": "A customer may put the cart down only at the designated service-counter return location.",
    "abstraction": {
      "state_properties": {
        "at_service_counter": "at(0,1)",
        "away_from_service_counter": {
          "not": "at_service_counter"
        }
      },
      "events": {
        "improper_cart_drop": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_service_counter"
            ]
          },
          "post": null
        },
        "proper_cart_drop": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "at_service_counter"
            ]
          },
          "post": "cartAt(0,1)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improper_cart_drop"
    }
  },
  {
    "id": "exit_without_cart",
    "text": "Customers are forbidden from exiting the supermarket while still holding or pushing a shopping cart.",
    "abstraction": {
      "state_properties": {
        "at_exit": "at(9,5)",
        "possessing_cart": "hasCart"
      },
      "events": {
        "cart_exit_attempt": {
          "pre": {
            "and": [
              "at_exit",
              "possessing_cart",
              "EXIT"
            ]
          },
          "post": null
        },
        "pedestrian_exit": {
          "pre": {
            "and": [
              "at_exit",
              {
                "not": "possessing_cart"
              },
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_exit_attempt"
    }
  },
  {
    "id": "no_cart_past_egg_bay",
    "text": "Shopping carts must not be pushed east or south out of the egg-bay cell, so customers with carts must turn back there.",
    "abstraction": {
      "state_properties": {
        "at_egg_bay": "at(6,4)",
        "pushing_cart": "hasCart",
        "cart_forbidden_far_aisle": {
          "and": [
            "hasCart",
            {
              "or": [
                "at(7,4)",
                "at(8,4)"
              ]
            }
          ]
        }
      },
      "events": {
        "push_cart_east_from_egg_bay": {
          "pre": {
            "and": [
              "at_egg_bay",
              "pushing_cart",
              "E"
            ]
          },
          "post": "at(7,4)"
        },
        "push_cart_south_from_egg_bay": {
          "pre": {
            "and": [
              "at_egg_bay",
              "pushing_cart",
              "S"
            ]
          },
          "post": "at(6,5)"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "push_cart_east_from_egg_bay",
          "push_cart_south_from_egg_bay",
          "cart_forbidden_far_aisle"
        ]
      }
    }
  }
]
